"""Detect and describe executables made by the original Blitz compilers (proof of concept for blitz-recompiler).

Blitz3D and BlitzPlus executables are a runtime stub plus the compiled program as one RT_RCDATA resource (id 1111).
The program is a relocatable x86 module: the code, then three symbol tables (labels, runtime references and data
references). This script finds that resource, parses the tables and reports what the program needs from the runtime,
and how much of that BlitzLLVM already provides (read from code_compiler/source/builtins.inc).

    blitz_exe_info.py program.exe                 summary
    blitz_exe_info.py program.exe --functions     also list the program's own functions
    blitz_exe_info.py program.exe --commands      also list every runtime command the program calls
    blitz_exe_info.py program.exe --disasm NAME   disassemble one function (needs the capstone module)
"""
import argparse
import collections
import os
import re
import struct
import sys

MODULE_RESOURCE_ID = 1111
RT_RCDATA = 10


class NotBlitz(Exception):
	pass


def u16(d, o):
	return struct.unpack_from('<H', d, o)[0]


def u32(d, o):
	return struct.unpack_from('<I', d, o)[0]


def find_resource(d, rtype, rid):
	"""Return the bytes of the first language of resource (rtype, rid) of a PE file."""
	if d[:2] != b'MZ':
		raise NotBlitz('not a PE file')
	pe = u32(d, 0x3C)
	if d[pe:pe + 4] != b'PE\0\0':
		raise NotBlitz('not a PE file')
	nsec = u16(d, pe + 6)
	opt = pe + 24
	magic = u16(d, opt)
	if magic != 0x10B:
		raise NotBlitz('not a 32-bit PE file (Blitz programs are x86)')
	ddir = opt + 96
	res_rva, res_size = u32(d, ddir + 2 * 8), u32(d, ddir + 2 * 8 + 4)
	sects = []
	for i in range(nsec):
		s = opt + u16(d, pe + 20) + i * 40
		vsize, va, rsize, raw = struct.unpack_from('<IIII', d, s + 8)
		sects.append((va, max(vsize, rsize), raw))

	def off(rva):
		for va, size, raw in sects:
			if va <= rva < va + size:
				return rva - va + raw
		raise NotBlitz('bad RVA')

	if not res_rva:
		raise NotBlitz('no resources')
	base = off(res_rva)

	def entries(dir_off):
		n = u16(d, dir_off + 12) + u16(d, dir_off + 14)
		for i in range(n):
			name, ptr = struct.unpack_from('<II', d, dir_off + 16 + i * 8)
			yield name, ptr

	for tname, tptr in entries(base):
		if tname != rtype or not tptr & 0x80000000:
			continue
		for iname, iptr in entries(base + (tptr & 0x7FFFFFFF)):
			if iname != rid or not iptr & 0x80000000:
				continue
			for _, lptr in entries(base + (iptr & 0x7FFFFFFF)):
				rva, size = struct.unpack_from('<II', d, base + lptr)
				o = off(rva)
				return d[o:o + size]
	raise NotBlitz('no program resource (RCDATA %d)' % MODULE_RESOURCE_ID)


class Module:
	"""The compiled program: code blob plus labels, runtime references and data references."""

	def __init__(self, blob):
		try:
			self.size = u32(blob, 0)
			self.code = blob[4:4 + self.size]
			p = 4 + self.size
			tables = []
			for _ in range(3):
				n = u32(blob, p)
				p += 4
				t = []
				for _ in range(n):
					e = blob.index(b'\0', p)
					name = blob[p:e].decode('latin1')
					t.append((name, u32(blob, e + 1)))
					p = e + 5
				tables.append(t)
			if p != len(blob) or len(self.code) != self.size:
				raise ValueError('trailing data')
		except (ValueError, struct.error) as e:
			raise NotBlitz('resource is not a Blitz module (%s)' % e)
		self.labels, self.calls, self.datarefs = tables
		self.defined = {n: v for n, v in self.labels}

	def kind(self, name):
		"""Symbol classes, as named by the original compiler."""
		if name.startswith('__'):
			return 'section' if name in ('__MAIN', '__DATA', '__LIBS') else 'support'
		if re.fullmatch(r'_\d+(_begin|_leave)?', name):
			return 'label'
		return {'f': 'function', 'v': 'global', 'a': 'array', 't': 'type'}.get(name[1:2], 'other')


def load_builtins(root):
	"""lowercase command name -> (runtime symbol, signature) from builtins.inc."""
	path = os.path.join(root, 'code_compiler', 'source', 'builtins.inc')
	out = {}
	try:
		with open(path, encoding='utf-8') as f:
			for line in f:
				m = re.match(r'\s*\{\s*"([a-z0-9_]+)",\s*"(\w+)",\s*\'(\w)\',\s*"(\w*)"', line)
				if m:
					out[m.group(1)] = (m.group(2), m.group(3) + ':' + m.group(4))
	except OSError:
		return None
	return out


def main():
	ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
	ap.add_argument('exe')
	ap.add_argument('--functions', action='store_true')
	ap.add_argument('--commands', action='store_true')
	ap.add_argument('--disasm', metavar='NAME')
	a = ap.parse_args()

	with open(a.exe, 'rb') as f:
		d = f.read()
	try:
		mod = Module(find_resource(d, RT_RCDATA, MODULE_RESOURCE_ID))
	except NotBlitz as e:
		print('%s: not a Blitz executable (%s)' % (a.exe, e))
		return 1

	kinds = collections.Counter(mod.kind(n) for n, _ in mod.labels)
	print('%s: Blitz program module' % a.exe)
	print('  code+data  %d bytes (x86, 32-bit)' % mod.size)
	print('  functions  %d   globals %d   arrays %d   types %d   labels %d'
		% (kinds['function'], kinds['global'], kinds['array'], kinds['type'], kinds['label']))
	print('  call sites %d   data references %d' % (len(mod.calls), len(mod.datarefs)))

	ext = collections.Counter(n for n, _ in mod.calls if n not in mod.defined)
	support = sorted(n for n in ext if n.startswith('__'))
	commands = sorted(n for n in ext if n.startswith('_f'))
	print('  compiler support functions needed: %d' % len(support))
	print('    ' + ' '.join(support))
	builtins = load_builtins(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
	if builtins is None:
		print('  runtime commands needed: %d (builtins.inc not found, no coverage check)' % len(commands))
		known = None
	else:
		known = [c for c in commands if c[2:] in builtins]
		print('  runtime commands needed: %d, found in BlitzLLVM builtins.inc: %d' % (len(commands), len(known)))
		missing = [c[2:] for c in commands if c[2:] not in builtins]
		if missing:
			print('    not in builtins.inc: ' + ' '.join(missing))
	if a.commands:
		for c in commands:
			b = builtins.get(c[2:]) if builtins else None
			print('    %-28s x%-5d %s' % (c[2:], ext[c], '%s (%s)' % b if b else '-'))
	if a.functions:
		for n, v in sorted((n, v) for n, v in mod.labels if mod.kind(n) == 'function'):
			print('    %08x %s' % (v, n[2:]))
	if a.disasm:
		try:
			import capstone
		except ImportError:
			print('--disasm needs the capstone module (pip install capstone)')
			return 1
		name = '_f' + a.disasm.lower()
		if name not in mod.defined:
			print('no function %s' % a.disasm)
			return 1
		start = mod.defined[name]
		end = min([v for _, v in mod.labels if v > start] or [mod.size])
		ref = {v + i: n for n, v in mod.calls + mod.datarefs for i in range(4)}
		for i in capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_32).disasm(mod.code[start:end], start):
			note = next((ref[k] for k in range(i.address, i.address + i.size) if k in ref), '')
			print('%08x  %-6s %-28s %s' % (i.address, i.mnemonic, i.op_str, note))
	return 0


if __name__ == '__main__':
	sys.exit(main())
